import{_ as l,l as o,o as e,c as n,v as t,p as h,x as r,d,i as s,S as m}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"衍射与空间频率","description":"","frontmatter":{"title":"衍射与空间频率","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/diffraction-spatial-freq.md","filePath":"litho/diffraction-spatial-freq.md","lastUpdated":1789023840000}'),p={name:"litho/diffraction-spatial-freq.md"};function c(_,a,f,A,E,b){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="衍射与空间频率" tabindex="-1">衍射与空间频率 <a class="header-anchor" href="#衍射与空间频率" aria-label="Permalink to &quot;衍射与空间频率&quot;">​</a></h1><div class="epigraph"><p>有限物体把入射场切出一套平面波；每一级衍射对应一个空间频率，透镜能做的，只是收集其中进得去的那些。</p><footer>—— 据 Abbe 成像原理与 Goodman, Introduction to Fourier Optics 整理</footer></div><p><a href="/litho/fresnel-fraunhofer">上一课</a>（菲涅尔与夫琅禾费）。在此之上，单色场收成复振幅、折射率与光程，相位已经可以沿路径积分。缺口是：掩模不是无限均匀介质，开口有限宽。有限物体把入射平面波衍射成许多传播方向，每个方向对应一个空间频率。本课只钉衍射与空间频率的接口；透镜能收集多高的频率，是 <a href="/litho/lens-na">数值孔径</a> 留下的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若仍只用光线穿过铬缝，缝边缘的场会不连续，亥姆霍兹方程不允许这样的解。正确的下一步是把掩模透过率 \\(t(x,y)\\) 当成物面的复振幅调制，出射场在自由空间里按角谱传播。周期为 \\(p\\) 的线栅把入射波劈成离散衍射级；非周期图形则是连续谱。没有「空间频率」这个轴，后课的光瞳、部分相干和 \\(k_1\\) 都没有自变量。</p><p>缺口因此不是「显微镜能不能分辨两点」，而是：先把物体写成空间频率的叠加，使后课的镜头成为这个轴上的低通滤波器。</p><h3 id="衍射级不是装饰-是成像的通道" tabindex="-1">衍射级不是装饰，是成像的通道 <a class="header-anchor" href="#衍射级不是装饰-是成像的通道" aria-label="Permalink to &quot;衍射级不是装饰，是成像的通道&quot;">​</a></h3><p>一维周期掩模、正入射、真空外侧，第 \\(m\\) 级的正弦条件是 \\(\\sin\\theta_m = m\\lambda/p\\)。\\(m=0\\) 沿轴走，\\(|m|\\ge 1\\) 偏到轴外。空中像的调制来自至少两个级在像面的干涉；若只剩零级，强度没有空间结构。本课不讨论哪些级进得了镜头，只承认：物体的傅里叶分量与这些传播方向一一对应。</p><p><span class="marginnote">空间频率的单位是 1/长度。光刻里常把 \\(f_x=n\\sin\\theta/\\lambda\\) 写在物镜光瞳坐标上。\\(n\\) 来自<a href="/litho/em-wave-index">上一课</a>，不要在这里把 \\(\\lambda\\) 改成介质波长却忘了 \\(n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Goodman 的角谱说法：把 \\(z=0\\) 的场做傅里叶分解，每个空间频率 \\((f_x,f_y)\\) 对应一个平面波，其波矢的横向分量 \\(k_x=2\\pi f_x\\)。传播一段距离只给该分量乘相位因子 \\(\\exp(i k_z z)\\)，\\(k_z=\\sqrt{n^2 k_0^2-k_x^2-k_y^2}\\)。evanescents（\\(k_x^2+k_y^2\\gt n^2 k_0^2\\)）沿 \\(z\\) 指数衰减，普通投影光学收集不到。</p><p>阿贝的说法更短：物体衍射，镜头把衍射级当光源再干涉成像。两套语言同一件事：有限孔径的信息上限是它收得进的最高 \\(|f|\\)。周期图形的级是 \\(\\delta\\) 梳；孤立图形的谱是连续包络。计算光刻把掩模的 \\(t(x,y)\\) 变换到这个频率轴上，再乘光瞳函数。</p><h3 id="斜入射只是把梳整体平移" tabindex="-1">斜入射只是把梳整体平移 <a class="header-anchor" href="#斜入射只是把梳整体平移" aria-label="Permalink to &quot;斜入射只是把梳整体平移&quot;">​</a></h3><p>照明若以角度 \\(\\theta_\\mathrm{ill}\\) 入射，衍射级相对光瞳中心平移 \\(n\\sin\\theta_\\mathrm{ill}/\\lambda\\)。后课的离轴照明靠的就是这条平移，让本会掉出光瞳的一级重新进来。本课不选光瞳形状，只留下：空间频率轴可以相对照明方向移动，物体本身的周期并未改变。</p><p><span class="marginnote">不要把「衍射极限」四个字在本课写成 \\(0.61\\lambda/\\mathrm{NA}\\)。那是后课的产线判据。本课的极限只是：高于 \\(n/\\lambda\\) 的横向频率在均匀介质里不能传播。</span></p>',15)),(e(),h(m,null,{default:r(()=>[s(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E9%80%8F%E8%BF%87%E7%8E%87%20t(x)%22%5D%20--%3E%20FT%5B%22%E7%A9%BA%E9%97%B4%E9%A2%91%E8%B0%B1%22%5D%0A%20%20FT%20--%3E%20ORD%5B%22%E8%A1%8D%E5%B0%84%E7%BA%A7%20%2F%20%E8%A7%92%E8%B0%B1%22%5D%0A%20%20ORD%20--%3E%20PROP%5B%22%E8%87%AA%E7%94%B1%E7%A9%BA%E9%97%B4%E4%BC%A0%E6%92%AD%22%5D%0A%20%20PROP%20--%3E%20PUP%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%85%89%E7%9E%B3%E6%88%AA%E6%96%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>铬缝的锐边拥有很宽的频谱。镜头若是理想低通，像面的边会变缓，对比度下降——这就是「衍射模糊」的频率说法，不必先画艾里斑。艾里斑是圆孔光瞳对点物的脉冲响应，是本课频谱截断的一个特例；后课引入 \\(\\mathrm{NA}\\) 之后再写它。</p><p>相位物体同样衍射。光程台阶（相移掩模）改变的是 \\(t(x)\\) 的辐角，频谱里会出现与纯振幅铬不同的级权重。本课只要求把 \\(t\\) 当成复数；\\(180^\\circ\\) 相移如何压零级，是掩模课的缺口。</p><h3 id="缩比把频率轴一起缩放" tabindex="-1">缩比把频率轴一起缩放 <a class="header-anchor" href="#缩比把频率轴一起缩放" aria-label="Permalink to &quot;缩比把频率轴一起缩放&quot;">​</a></h3><p>\\(4\\times\\) 投影把掩模坐标缩小到晶圆。空间频率按缩比放大：掩模上较疏的周期，在晶圆上变成更密的频率。讨论「哪一级进光瞳」时，必须声明频率是在物方还是像方。惯例是把光瞳坐标归一到像方 \\(\\mathrm{NA}/\\lambda\\)。本课不引入 \\(\\mathrm{NA}\\)，只警告：缩比不是把同一张频谱图贴到晶圆上。</p><p>周期为 \\(p\\) 的线栅把入射波劈成离散级 \\(m\\lambda/p\\)；非周期图形是连续谱。空中像的调制来自至少两个级在像面干涉——若只剩零级，强度没有空间结构。本课不讨论哪些级进得了镜头，只承认物体的傅里叶分量与传播方向一一对应。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课用标量角谱，忽略掩模吸收体的厚度。真实铬或 MoSi 有几十纳米的高度，电磁边界条件会改各级的复振幅，那是<a href="/litho/mask-3d-effect">掩模 3D</a> 的缺口。也不处理部分相干：单色平面波照明下的衍射级是确定的；扩展光源要把许多入射方向的强度非相干相加，留给<a href="/litho/partial-coherence">部分相干</a>。</p><p>空间频率不是「分辨率」的同义词。分辨率还要胶把连续强度切成线宽。本课结束时，后课可以谈论光瞳，但还不能写 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限掩模把单色场分解为空间频率；周期图形对应离散衍射级。</li><li>可传播的横向频率不超过 \\(n/\\lambda\\)；更高的是倏逝波。</li><li>空中像的调制来自至少两个频率分量在像面干涉。</li><li>斜照明平移频谱，为后课离轴照明预留接口。</li><li>本课不引入 \\(\\mathrm{NA}\\)，不写瑞利 CD 公式。</li><li>出处：Abbe 成像原理；Goodman, <em>Introduction to Fourier Optics</em>。</li></ul>',11))])}const k=l(p,[["render",c]]);export{x as __pageData,k as default};
